insert into seasons (id, name, year, is_current) values (1, 'Season 35', 2026, true);
insert into couples (id, season_id, celeb, pro, known_for, tier, position, grade, floor, ceiling, comp, vote_engine, bio, red_flag, eliminated_week) values
  (1, 1, 'Jenna Dewan', 'Val Chmerkovskiy', 'Step Up, The Rookie', 1, 'Franchise quarterback', 'A+', 22, 30, 'Jordan Fisher, S25 champion', 'Step Up nostalgia, The Rookie', 'Toured behind Janet Jackson and Missy Elliott, made Step Up a franchise, then hosted World of Dance and judged SYTYCD, which means she has literally been paid to evaluate the thing she''s now competing in. Paired with Val, who has two Mirrorballs and no interest in third place. This is the Nicole Scherzinger problem: the show cast a professional and everyone is going to act surprised.', 'The judges'' only move is to score her a 7 in week one "for growth." Budget for it.', null),
  (2, 1, 'Harry Shum Jr.', 'Jenna Johnson', 'Glee, Grey''s Anatomy', 1, 'Two-way superstar', 'A', 21, 30, 'Corbin Bleu, S17 runner-up', 'Glee, Grey''s, Everything Everywhere', 'Mike Chang on Glee was a dancer who got cast as an actor, not the other way around. Backup dancer for Beyoncé, JLo and Mariah, two Step Up sequels, and a Crazy Rich Asians spinoff on deck. Jenna Johnson has won this show. The scary part isn''t the technique, it''s that he can act the story of a rumba, which is what separates a 27 from a 30.', 'Dewan already claimed the "wait, they''re a real dancer?" storyline, and the show only writes one of those per season.', null),
  (3, 1, 'Amber Glenn', 'Pasha Pashkov', 'Olympic figure skating', 1, 'Elite athlete, musical', 'A', 20, 30, 'Kristi Yamaguchi, S6 champ · Meryl Davis, S18 champ', 'Fresh off the 2026 Games', 'Olympic gold medalist, three-time U.S. champion, first American woman to land three triple Axels at one Games. Figure skaters have the best track record of any athlete category on this show because the job is already "perform choreography to music while judges hold up numbers." The first openly LGBTQ+ U.S. women''s champion, with a fanbase that votes like it''s a tournament.', 'Skaters sometimes look like they''re waiting for the ice to show up. Pasha will fix that by week 3.', null),
  (4, 1, 'Tatyana Ali', 'Jan Ravnik', 'The Fresh Prince of Bel-Air', 1, 'Veteran, Broadway pedigree', 'A−', 19, 29, 'Alfonso Ribeiro, S19 champion', 'Fresh Prince, Abbott Elementary', 'Ashley Banks, all six seasons. Broadway in Fences. Five NAACP Image Awards. And here''s the plot: her TV brother Carlton won this show and is now standing at the podium hosting it. That''s not a storyline, that''s a season-long arc the producers are going to milk until it screams.', 'Everyone''s going to yell "do the Carlton" and at some point, God help her, she will.', null),
  (5, 1, 'Julia Stiles', 'Ezra Sosa', '10 Things I Hate About You', 2, 'Sleeper with a résumé', 'B+', 18, 28, 'Zendaya, S16 runner-up (minus the youth)', 'Every millennial who owned a Save the Last Dance DVD', 'Emmy and Golden Globe nominee, Kat Stratford, Bourne, Dexter, and a feature directing debut in 2025. But the whole league knows what this is about: in 2001 she did ballet-to-hip-hop for two hours in Save the Last Dance, and either that training is still in there or it isn''t. Ezra Sosa choreographs like he''s auditioning for a Mirrorball, which he is.', 'An actress this good at playing reserved may take three weeks to look like she''s enjoying herself. The judges score joy.', null),
  (6, 1, 'Ezra Frech', 'Daniella Karagach', 'Paralympic gold medalist', 2, 'Elite athlete, explosive', 'B+', 18, 29, 'Amy Purdy, S18 runner-up · Noah Galloway, S20 third', 'Paralympic gold, motivational-speaker charisma', 'Paralympic gold medalist, world-record holder, co-founder of Angel City Sports, and a professional speaker, which means he already knows how to hold a room for ninety seconds. Daniella Karagach won a Mirrorball with an NBA player and has a documented gift for turning athletes into dancers by week 4. A producer''s dream, and the judges will be generous with the growth arc.', 'None. If you draft against him at the watch party you are going to have to explain yourself.', null),
  (7, 1, 'Jackson Olson', 'Emma Slater', 'Savannah Bananas', 2, 'Athlete who dances for a living', 'B+', 17, 28, 'Ilona Maher, S33 runner-up', 'Savannah Bananas social media, which is enormous', 'Plays for the Savannah Bananas, a baseball team whose entire business model is choreographed dance breaks between innings. So: a professional athlete with hundreds of reps performing rehearsed routines in sold-out stadiums, plus a following that already knows how to vote on their phones. Emma Slater has a Mirrorball and a reputation for making big guys look light.', 'Banana Ball choreography is 40% hip thrust. The paso doble is not.', null),
  (8, 1, 'Conner Leavitt', 'Adele Zaikman', 'The Secret Lives of Mormon Wives', 2, 'The sequel, in a good way', 'B', 17, 27, 'His wife, one season ago', 'The entire Mormon Wives audience, redirected', 'Whitney Leavitt went deep in season 34; now the "Instagram husband" gets his turn. Except he isn''t just a plus-one: he made his off-Broadway debut in May, so there''s stage training. Partnered with Adele Zaikman, the rookie pro who won The Next Pro and will be dancing like her contract depends on it. He also has a live-in coach who knows what Carrie Ann is going to say before she says it.', 'Rookie pros historically go home early. Also his household now contains two people who''ve done this, which is either a superpower or a divorce.', 1),
  (9, 1, 'Tyler Cameron', 'Sharna Burgess', 'The Bachelorette', 2, 'Athletic, coachable, tall', 'B', 17, 27, 'Hannah Brown, S28 champion (yes, that one)', 'Bachelor Nation, HGTV crossover', 'Former college football player, runner-up on Hannah Brown''s Bachelorette, and the franchise''s most famous case of losing the girl and winning the internet. Hannah then won this show, so there is a narrative. Sharna Burgess is back after five years away and won her Mirrorball with a radio host who could not dance, which tells you what she does with a man who takes direction.', '6''4" in a jive. Long limbs are a cha-cha problem until they aren''t.', null),
  (10, 1, 'Taylor Hanson', 'Britt Stewart', 'Hanson', 2, 'Musician, rhythm-first', 'B', 17, 27, 'Joey Fatone, S4 runner-up', 'Thirty years of Hanson fans, seven children', 'The middle Hanson, keys and lead vocals, famous since 1997, still touring. Musicians reliably hear the count, and keys players hear it best. Father of seven, so the "I''ve never had a moment to myself" package writes itself. Britt Stewart is a strong technician who''s been waiting for a partner with rhythm.', 'Hearing the beat and moving your hips on it are, tragically, different skills. Ask every guitarist who''s ever been on this show.', null),
  (11, 1, 'Guillermo Rodriguez', 'Witney Carson', 'Jimmy Kimmel Live!', 3, 'Fan-vote monster · low ceiling', 'C+', 12, 22, 'Bobby Bones, S27 champion, the darkest day in judging history', '23 years of Kimmel viewers, every Oscars red carpet', 'Discovered as a parking-lot security guard, now the most beloved man in late night. The paddles will be cruel and it will not matter, because America will vote for him until he''s physically dragged from the ballroom. The half-points-if-eliminated rule was written with him in mind, in the opposite direction: he''s the safest low-score pick on the board. Ride or Die grade: A.', 'He will outlast someone with a 28. Everyone at the party will say the show is rigged. The show is not rigged, it''s just Guillermo.', null),
  (12, 1, 'Maura Higgins', 'Mark Ballas', 'Love Island, The Traitors', 3, 'Reality all-star · high volatility', 'B−', 15, 26, 'Joey Graziadei, S33 champion', 'Love Island, The Traitors, the Birkin apology', 'Love Island UK breakout, Aftersun host, and runner-up on The Traitors after a betrayal that got weeks of coverage and an actual Birkin bag as an apology. That is a fanbase that does not forget and does vote. Mark Ballas is a three-time champion who came out of retirement once already to win with a TikTok star; he does not come back for fun.', 'Scores may lag the votes by a lot, so as a weekly pick she''s a coin flip. As a Ride or Die she''s sneaky great.', null),
  (13, 1, 'Connor Wood', 'Rylee Arnold', 'Fibula, comedian & podcaster', 3, 'Internet · unknown skill', 'C+', 14, 25, 'Alix Earle, S34', '1.3M followers, a national comedy tour, NBC Olympics gig', '"Fibula" to his followers, co-host of Brooke and Connor Make a Podcast, and a working stand-up who put Ilana Glazer on his tour. Comedians survive on this show because the packages are funny and the votes follow. Rylee Arnold has been to the finale already and picks choreography like she''s trying to end careers. Wildly unknown floor.', 'If he''s bad, he will be bad on purpose for the bit, and the judges have no idea how to score a bit.', null),
  (14, 1, 'Ciara Miller', 'Brandon Armstrong', 'Summer House', 3, 'Bravo · momentum play', 'C+', 15, 25, 'Ariana Madix, S32 finalist', 'Summer House, plus a 2026 betrayal storyline the internet took personally', 'Summer House''s most influential export, per Bravo, and this year the wronged party in a public ex-and-friend situation that turned a whole fanbase into a voting bloc. The Ariana Madix precedent is instructive: Bravo women with a grievance and a good pro make the finale. Brandon Armstrong has never had a partner with this much narrative wind at her back.', 'It''s a nurse''s schedule and a Bravo schedule and a DWTS rehearsal schedule. Something''s giving.', null),
  (15, 1, 'Sarah Jane Nader', 'Hailey Bills', 'Love Thy Nader', 3, 'Same-sex pairing · rookie pro', 'C', 14, 24, 'Her sister Brooks, S33, ninth place', 'Love Thy Nader, the Nader sister multiverse', 'Actress, model, star of Love Thy Nader, and the second Nader sister to enter the ballroom after Brooks went out ninth. The season''s same-sex pairing, with Hailey Bills promoted from the ensemble to pro. First-year pros go home early far more often than not, but a same-sex partnership means both dancers can lead and follow, and the choreography can go places the standard pairings can''t.', 'Four other reality stars are splitting the same vote. Someone from this tier goes home week 2 and it''s probably not Guillermo.', 2),
  (16, 1, 'Giada De Laurentiis', 'Alan Bersten', 'Food Network', 3, 'Celebrity chef · veteran presence', 'C', 13, 23, 'Carole Baskin''s scores, Paula Deen''s exit', 'Fifteen seasons of Everyday Italian, everyone''s mom', 'Emmy winner, restaurateur, the face of Food Network for two decades. Chefs have not historically done well here, but chefs have also not historically been paired with Alan Bersten, a champion who can teach anyone a Viennese waltz. She''s camera-trained, composed under pressure, and used to doing precise things with her hands while someone counts down. That''s more relevant than it sounds.', 'Every package will involve a kitchen. Every one. Bruno will make a pasta joke and it will cost her a point.', null);
